templates.body:
index={{var:index}} sourcetype="WinEventLog:Security" (EventCode=4720 OR EventCode=4722 OR EventCode=4728 OR EventCode=4732) earliest=-{{var:range}}
| table _time, host, EventCode, Account_Name, Target_Account_Name, Group_Name
| sort - _time

index={{var:index}} sourcetype="WinEventLog:System" EventCode=7045 earliest=-{{var:range}}
| table _time, host, Service_Name, Service_File_Name, Service_Type, Service_Start_Type
| sort - _time

index={{var:index}} (EventCode=4698 OR (EventCode=4688 New_Process_Name="*\\schtasks.exe")) earliest=-{{var:range}}
| table _time, host, user, Task_Name, New_Process_Name, CommandLine
| sort - _time

index={{var:index}} (EventCode=1102 OR EventCode=104) earliest=-{{var:range}}
| table _time, host, user, EventCode, Message
| sort - _time

index={{var:index}} (sourcetype="WinEventLog:Microsoft-Windows-Windows Defender/Operational" (EventCode=5001 OR EventCode=5007 OR EventCode=5010 OR EventCode=5012)) earliest=-{{var:range}}
| table _time, host, EventCode, Message
| sort - _time
